<script setup lang="ts">import{ref,onMounted,onUnmounted}from'vue';import{useGatewayStore}from'../stores/gateway';import Tooltip from'./Tooltip.vue'
interface Ms{name:string;transport:string;connected:boolean;enabled:boolean;state:string;tools:number;tool_names:string[];error?:string}
interface Mt{server:string;name:string}
interface Pr{installed:boolean;label:string;url:string;description:string}
interface Is{name:string;type:string;package:string;url:string;description:string;requires:string[]}
const g=useGatewayStore();const o=ref(false);const sr=ref<Ms[]>([]);const tl=ref<Mt[]>([]);const ld=ref(false)
const pr=ref<Record<string,Pr>>({});const mi=ref<Is[]>([]);const pend=ref<{path:string;servers:string[]}[]>([]);const approving=ref('')
async function lo(){ld.value=true;try{const r=await g.request<{servers:Ms[];tools:Mt[];pending_project_servers?:{path:string;servers:string[]}[]}>('mcp.list',{});sr.value=r.servers||[];tl.value=r.tools||[];pend.value=r.pending_project_servers||[]}catch{}finally{ld.value=false}
try{const r=await g.request<{prerequisites:Record<string,Pr>;servers:Is[]}>('mcp.install_info',{});pr.value=r.prerequisites||{};mi.value=r.servers||[]}catch{}}
async function approve(path:string){if(approving.value)return;approving.value=path;try{const r=await g.request<{ok:boolean;error?:string}>('mcp.trust_project',{path});if(r?.ok){await lo()}}catch{}finally{approving.value=''}}
function missingPrereqs():string[]{return Object.entries(pr.value).filter(([,v])=>!v.installed).map(([k])=>k)}
function dl(url:string){if(url)window.open(url,'_blank')}
function needDownload(name:string):Is|undefined{return mi.value.find(s=>s.name===name&&s.type==='download')}
function tg(){o.value=!o.value;if(o.value){lo();loSecrets()}}
const tokenOpen=ref('');const tokenVal=ref('');const tokenSaving=ref(false);const secretSt=ref<Record<string,Record<string,boolean>>>({})
async function loSecrets(){try{const r=await g.request<{secrets:Record<string,Record<string,boolean>>}>('mcp.secret_status',{});secretSt.value=r.secrets||{}}catch{}}
function tgToken(n:string){tokenOpen.value=tokenOpen.value===n?'':n;tokenVal.value=''}
const toggling=ref('')
async function toggleServer(n:string,en:boolean){if(toggling.value)return;toggling.value=n;const t=sr.value.find(s=>s.name===n);if(t){t.enabled=en;t.state=en?'connecting':'disabled'};try{const r=await g.request<{ok:boolean;enabled?:boolean;state?:string;error?:string}>('mcp.toggle',{server:n,enabled:en});if(r?.ok){if(t&&r.state)t.state=r.state;window.setTimeout(()=>{lo()},600)}else{if(t){t.enabled=!en;t.state=en?'disabled':'connected'}}}catch{if(t){t.enabled=!en;t.state=en?'disabled':'connected'}}finally{toggling.value=''}}
async function saveToken(n:string){const v=tokenVal.value.trim();if(!v||tokenSaving.value)return;tokenSaving.value=true;try{const r=await g.request<{ok:boolean;reconnected:boolean}>('mcp.set_secret',{server:n,env_key:'GITHUB_PERSONAL_ACCESS_TOKEN',value:v});if(r?.ok){tokenOpen.value='';tokenVal.value='';await loSecrets();lo()}}catch{}finally{tokenSaving.value=false}}
const optOpen=ref<Record<string,boolean>>({})
function isOptionalUnconfigured(s:Ms):boolean{if(s.connected||!needDownload(s.name))return false;const e=(s.error||'').toLowerCase();return e.includes('placeholder')||e.includes('has no sha256')||e.includes('not configured')}
function tgOpt(n:string){optOpen.value[n]=!optOpen.value[n]}
const installing=ref('');const installErr=ref('');const manualOpen=ref('');const manualPath=ref('')
async function doInstall(n:string){if(installing.value)return;installing.value=n;installErr.value='';try{const r=await g.request<{ok:boolean;exe_path?:string;error?:string}>('mcp.install_server',{server:n});if(r?.ok){manualOpen.value='';await lo()}else{installErr.value=r?.error||'install failed';manualOpen.value=n}}catch(e){installErr.value=String(e);manualOpen.value=n}finally{installing.value=''}}
async function saveManualPath(n:string){const v=manualPath.value.trim();if(!v)return;installErr.value='';try{const r=await g.request<{ok:boolean;error?:string}>('mcp.install_server',{server:n,path:v});if(r?.ok){manualOpen.value='';manualPath.value='';await lo()}else{installErr.value=r?.error||'save failed'}}catch(e){installErr.value=String(e)}}
onMounted(()=>{const h=(e:MouseEvent)=>{if(!o.value)return;const el=e.target as HTMLElement;if(!el.closest('.mc-panel')&&!el.closest('.mc-btn')){if(manualOpen.value&&manualPath.value.trim())return;o.value=false}};document.addEventListener('mousedown',h);const hm=()=>{if(o.value)lo()};window.addEventListener('gateway:mcp-state',hm);onUnmounted(()=>{document.removeEventListener('mousedown',h);window.removeEventListener('gateway:mcp-state',hm)})})
</script>
<template><Tooltip text="MCP Server Status" position="bottom"><button class="mc-btn" :class="{active:o}" @click="tg"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M7 17l-3 3"/><path d="M17 7l3-3"/><path d="M12 2l-2 4h4l-2-4z"/><path d="M10 6v4a2 2 0 002 2 2 2 0 002-2V6"/><path d="M8 12v4a4 4 0 008 0v-4"/></svg><span v-if="tl.length>0" class="mc-badge">{{tl.length}}</span></button></Tooltip>
<div v-if="o" class="mc-panel"><div class="mc-hdr"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M7 17l-3 3"/><path d="M17 7l3-3"/><path d="M12 2l-2 4h4l-2-4z"/><path d="M10 6v4a2 2 0 002 2 2 2 0 002-2V6"/><path d="M8 12v4a4 4 0 008 0v-4"/></svg><span class="mc-title">MCP Servers</span><Tooltip text="Refresh" position="bottom"><button class="mc-refresh" @click="lo"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 11-2.12-9.36L23 10"/></svg></button></Tooltip></div>
<div class="mc-body">
<div v-if="pend.length>0" class="mc-pending"><div class="mc-pending-title">Project config pending approval</div><div v-for="pp in pend" :key="pp.path" class="mc-pending-item"><div class="mc-pending-path">{{pp.path}}</div><div class="mc-pending-servers">{{pp.servers.length>0?pp.servers.join(', '):'(no servers)'}}</div><button class="mc-prereqs-btn" :disabled="approving===pp.path" @click="approve(pp.path)">{{approving===pp.path?'Approving...':'Approve'}}</button></div></div>
<div v-if="missingPrereqs().length>0" class="mc-prereqs"><div class="mc-prereqs-title">Missing Prerequisites</div><div v-for="k in missingPrereqs()" :key="k" class="mc-prereqs-item"><span class="mc-prereqs-name">{{k}}</span><span class="mc-prereqs-desc">{{pr[k]?.description}}</span><button v-if="pr[k]?.url" class="mc-prereqs-btn" @click="dl(pr[k].url)">{{pr[k]?.label}}</button></div></div>
<div v-if="ld&&sr.length===0" class="mc-empty">Loading...</div><div v-else-if="!ld&&sr.length===0" class="mc-empty">No MCP servers</div>
<div v-for="srv in sr" :key="srv.name" class="mc-srv" :class="{offline:!srv.connected}"><div class="mc-srv-hdr"><span class="mc-dot" :class="{on:srv.connected,off:!srv.connected}"/><span class="mc-srv-name">{{srv.name}}</span><span class="mc-srv-tools">{{srv.tools}} tools</span><span class="mc-status" :class="{up:srv.connected,down:!srv.connected,opt:isOptionalUnconfigured(srv),dis:srv.enabled===false}">{{srv.enabled===false?'Disabled':(srv.state==='connecting'||srv.state==='pending'?'Connecting':(srv.connected?'Connected':(srv.state==='failed'?'Failed':(isOptionalUnconfigured(srv)?'Optional':'Disconnected'))))}}</span><button class="mc-switch" :class="{on:srv.enabled!==false,off:srv.enabled===false,busy:toggling===srv.name}" :disabled="toggling===srv.name" @click="toggleServer(srv.name,srv.enabled===false)"><span class="mc-switch-knob"/></button></div><div v-if="srv.tool_names&&srv.tool_names.length>0" class="mc-tools"><span v-for="tn in srv.tool_names" :key="tn" class="mc-tool">{{tn}}</span></div><div class="mc-srv-ftp"><span class="mc-ftp-label">Transport</span><code class="mc-ftp-code">{{srv.transport}}</code></div><template v-if="srv.name==='github'"><div class="mc-srv-token"><span class="mc-token-label">Token</span><span class="mc-token-state" :class="{ok:secretSt[srv.name]?.['GITHUB_PERSONAL_ACCESS_TOKEN']}">{{ secretSt[srv.name]?.['GITHUB_PERSONAL_ACCESS_TOKEN'] ? 'Configured' : 'Not set' }}</span><button class="mc-token-btn" @click="tgToken(srv.name)">{{ tokenOpen===srv.name ? 'Close' : 'Set Token' }}</button></div><div v-if="tokenOpen===srv.name" class="mc-token-edit"><input type="password" v-model="tokenVal" class="mc-token-input" placeholder="ghp_..." spellcheck="false" @keydown.enter="saveToken(srv.name)"/><button class="mc-token-save" :disabled="!tokenVal.trim()||tokenSaving" @click="saveToken(srv.name)">{{ tokenSaving ? 'Saving...' : 'Save' }}</button></div></template><template v-if="!srv.connected&&needDownload(srv.name)"><div class="mc-srv-opt"><span class="mc-opt-badge">Optional</span><span class="mc-opt-hint">{{ isOptionalUnconfigured(srv) ? 'Not configured. Click Set path to select the downloaded exe.' : 'Not installed.' }}</span><button class="mc-prereqs-btn" @click="manualOpen=manualOpen===srv.name?'':srv.name">Set path</button><button class="mc-opt-more" @click="tgOpt(srv.name)">{{ optOpen[srv.name] ? 'Less' : 'More' }}</button></div><div v-if="manualOpen===srv.name" class="mc-token-edit"><input type="text" v-model="manualPath" class="mc-token-input" placeholder="C:\path\to\codebase-memory-mcp.exe" spellcheck="false" @keydown.enter="saveManualPath(srv.name)"/><button class="mc-token-save" :disabled="!manualPath.trim()" @click="saveManualPath(srv.name)">Save</button></div><div v-if="optOpen[srv.name]" class="mc-srv-more"><div class="mc-srv-dl"><span>{{ installing===srv.name ? 'Installing...' : 'Automatic install' }}</span><button class="mc-prereqs-btn" :disabled="!!installing" @click="doInstall(srv.name)">Install</button></div><div v-if="installErr&&manualOpen===srv.name" class="mc-srv-error">{{ installErr }}</div><div v-if="srv.error" class="mc-srv-error">{{srv.error}}</div></div></template><div v-else-if="srv.error" class="mc-srv-error">{{srv.error}}</div></div></div></div></template>
